create or replace function public.draft_has_any_price(p_proposed jsonb) returns boolean language sql immutable as $$ select (p_proposed ->> 'guest_post_cost') is not null or (p_proposed ->> 'guest_post_cost_written_by_publisher') is not null or (p_proposed ->> 'link_insertion_cost') is not null or (p_proposed ->> 'homepage_link_cost') is not null or (p_proposed ->> 'banner_cost') is not null or exists ( select 1 from jsonb_each(coalesce(p_proposed -> 'niches', '{}'::jsonb)) as n(slug, terms) where (n.terms ->> 'guest_post_cost') is not null or (n.terms ->> 'link_insertion_cost') is not null ); $$;
create or replace function public.draft_approval_batch( p_limit integer default 25, p_exclude uuid[] default '{}', p_relaxed boolean default false ) returns table ( id uuid, domain text, email_id uuid, matched_website_id uuid, proposed jsonb ) language sql stable security definer set search_path = public as $$ with contested as ( select c.domain from public.listing_drafts c where c.status in ('pending', 'approved') group by c.domain having count(*) > 1 ) select d.id, d.domain, d.email_id, d.matched_website_id, d.proposed from public.listing_drafts d where d.status = 'pending' and not (d.id = any (p_exclude)) and not exists (select 1 from contested x where x.domain = d.domain) and case when p_relaxed then public.draft_has_any_price(d.proposed) and not (d.flags && array['price-without-currency', 'different-site-offered']::text[]) else d.low_confidence_count = 0 and cardinality(d.flags) = 0 end order by d.id asc limit greatest(1, p_limit); $$;
create or replace function public.draft_approval_eligible_count( p_relaxed boolean default false ) returns integer language sql stable security definer set search_path = public as $$ with contested as ( select c.domain from public.listing_drafts c where c.status in ('pending', 'approved') group by c.domain having count(*) > 1 ) select count(*)::integer from public.listing_drafts d where d.status = 'pending' and not exists (select 1 from contested x where x.domain = d.domain) and case when p_relaxed then public.draft_has_any_price(d.proposed) and not (d.flags && array['price-without-currency', 'different-site-offered']::text[]) else d.low_confidence_count = 0 and cardinality(d.flags) = 0 end; $$;
